func RetryLimit(configured int) int {
    retries := configured
    if retries <= 0 {
        retries = 3 // zero o valor inválido: usa el default
    }
    return retries
}

func ScoreBand(score int) string {
    switch {
    case score >= 90:
        return "excellent"
    case score >= 60:
        return "passing"
    default:
        return "retry"
    }
}

func Divide(a, b int) (int, error) {
    if b == 0 {
        return 0, errors.New("division by zero")
    }
    return a / b, nil
}

