type PriceLookup interface {
    PriceFor(sku string) (int, error)
}

func Quote(source PriceLookup, sku string, quantity int) (int, error) {
    price, err := source.PriceFor(sku)
    if err != nil {
        return 0, err
    }
    return price * quantity, nil
}
